INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 11, 'theory', 'HTTP/1.1: requests, headers, status codes, cache and cookies');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 11, 0, 'Which status code means "the resource has moved permanently"?', '["200", "404", "503", "301"]', 3, '301 Moved Permanently; the new address is given in the Location header.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 11, 1, 'Which method is not idempotent, so repeating it blindly is dangerous?', '["POST", "GET", "PUT", "DELETE"]', 0, 'Repeating a POST can create a second record or a second order.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 11, 2, 'Why does HTTP/1.1 have the Host header?', '["To pass the content type", "To say which site is wanted when many sites share one IP address", "To turn on encryption", "To set the cache lifetime"]', 1, 'It is the basis of virtual hosting: the server picks the site by the Host header.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 11, 3, 'The server replied 304 Not Modified. What does it mean?', '["The page was deleted", "Authorization is required", "The client''s cached copy is current, so the body need not be sent", "Redirect to another site"]', 2, 'The client sent the ETag in If-None-Match; the server confirmed that the resource has not changed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 11, 4, 'Which cookie flag stops scripts on the page from reading the value?', '["Secure", "HttpOnly", "SameSite", "Path"]', 1, 'HttpOnly protects the session identifier from theft through XSS.');
